const sessionUser=JSON.parse(sessionStorage.getItem('shotcraftUser')||'{}');
document.body.classList.add('photographer-app');
const app=document.getElementById('app');
let timelineRequest=0;
const timelineMarkup=items=>`<section class="shared-timeline"><div class="eyebrow">Shoot journey</div><div class="timeline-track">${(items||[]).map(item=>`<div class="timeline-item ${item.completed?'complete':''}"><span class="timeline-dot">${item.completed?'✓':''}</span><div><b>${esc(item.label)}</b><small>${item.timestamp?esc(item.timestamp):'Upcoming'}</small></div></div>`).join('')}</div></section>`;
async function refreshTimeline(){const id=app.dataset.timelineId;if(!id)return;const request=++timelineRequest;try{const response=await fetch(`/api/inquiries/${id}/timeline`,{cache:'no-store'}),data=await response.json();if(request!==timelineRequest)return;const existing=document.querySelector('.shared-timeline');if(existing)existing.outerHTML=timelineMarkup(data.timeline);else {const legacy=document.querySelector('.progress');if(legacy)legacy.outerHTML=timelineMarkup(data.timeline);else app.insertAdjacentHTML('beforeend',timelineMarkup(data.timeline))}}catch(_){} }
const briefCache=new Map();
let inquiries=[],cityImages={};
let current={view:'overview',id:null};
document.getElementById('photographerName').textContent=sessionUser.name||'Photographer';
document.getElementById('photographerEmail').textContent=sessionUser.email||'';
document.querySelector('.brand').innerHTML='<span class="brand-mark">S</span><span class="brand-copy"><b>ShotCraft</b><small>Creative workspace</small></span>';
document.querySelector('.identity').insertAdjacentHTML('afterbegin','<span class="profile-orb" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7 8a7 7 0 0 0-14 0"/></svg></span>');
document.querySelector('.identity').insertAdjacentHTML('beforeend','<span class="account-menu">•••</span>');
document.querySelector('.nav').innerHTML='<div class="nav-label">Workspace</div><button data-view="overview"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 11 12 4l8 7v9h-5v-6H9v6H4Z"/></svg></span><span>Overview</span></button><button data-view="inquiries"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 6.5h16v11H4zM8 10h8M8 14h5"/></svg></span><span>Inquiry inbox</span><span class="nav-count" id="inboxCount"></span></button><button data-view="projects"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 7h6l2-2h8v14H4Z"/></svg></span><span>Active projects</span></button><button data-view="calendar"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M5 5h14v15H5zM8 3v4M16 3v4M5 9h14"/></svg></span><span>Shoot calendar</span></button>';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const parse=value=>{try{return typeof value==='string'?JSON.parse(value):value}catch{return null}};
const formatDate=value=>{if(!value)return'Date flexible';const date=new Date(value);const hasTime=value.includes('T')||/^\d{4}-\d{2}-\d{2}\s/.test(value);return Number.isNaN(date.valueOf())?value:date.toLocaleString(undefined,{dateStyle:'medium',...(hasTime?{timeStyle:'short'}:{})})};
function payload(record){return parse(record.payload)||{}}
function statusInfo(record){if(record.status==='SCHEDULED')return['SHOOT SCHEDULED','scheduled'];if(record.status==='CLIENT_CONFIRMED')return['CLIENT CONFIRMED','ready'];if(record.status==='CLIENT_CHANGE_REQUESTED')return['CHANGE REQUESTED','needs'];if(record.production_approved)return['PLAN SHARED','ready'];if(record.production_pack)return['PLAN READY','ready'];if(record.moodboard)return['MOODBOARD READY','ready'];if(record.status==='READY_FOR_REVIEW')return['READY TO PLAN','ready'];if(record.status==='NEEDS_INFORMATION')return['AWAITING CLIENT','needs'];return[record.status.replaceAll('_',' '),'']}
function setNav(view){document.querySelectorAll('.nav button').forEach(button=>button.classList.toggle('active',button.dataset.view===view||(['project','brief','production','schedule'].includes(view)&&button.dataset.view==='projects')))}
function go(view,id=null,push=true){current={view,id:id?Number(id):null};if(push){const params=new URLSearchParams();if(view!=='overview')params.set('view',view);if(id)params.set('id',id);history.pushState(current,'','/photographer'+(params.size?'?'+params:''))}renderCurrent()}
function recordCard(record){const p=payload(record),status=statusInfo(record);return`<article class="card project"><div class="row"><div><b>${esc(p.client_name||'Unnamed client')}</b><p class="project-summary">${esc((p.message||'').slice(0,180))}${(p.message||'').length>180?'…':''}</p></div><span class="status ${status[1]}">${status[0]}</span></div><div class="meta"><div>Shoot date<b>${esc(formatDate(p.shoot_date))}</b></div><div>Budget<b>${p.budget?'$'+esc(p.budget):'Not specified'}</b></div></div><button class="primary" data-project="${record.id}">Open project →</button></article>`}
function projectTitle(record){const p=payload(record),analysis=parse(record.analysis)||{};return analysis.concept_name||p.shoot_type||p.message?.split(/[.!?]/)[0]?.slice(0,58)||`${p.client_name||'Client'} shoot`}
function projectLocation(record){const p=payload(record),text=[p.message,record.meeting_location].filter(Boolean).join(' '),city=text.match(/Seattle|Delhi|New Delhi/i)?.[0]?.toLowerCase().replace('new delhi','delhi');return{city,label:record.meeting_location||(city==='delhi'?'Delhi, India':city==='seattle'?'Seattle, Washington':'Location being planned')}}
function galleryProject(record,index){const p=payload(record),status=statusInfo(record),place=projectLocation(record),gallery=cityImages[place.city]?.gallery||[],image=gallery.length?gallery[index%gallery.length]:null;return`<article class="gallery-card ${index===0?'gallery-featured':''}">${image?`<img src="${esc(image)}" alt="${esc(place.label)} city view" loading="lazy">`:''}<div class="gallery-shade"></div><button class="circle-action" data-project="${record.id}" aria-label="Open ${esc(projectTitle(record))}">→</button><div class="gallery-content"><div class="eyebrow">${esc(p.client_name||'Client')} · ${esc(formatDate(p.shoot_date))}</div><h2>${esc(projectTitle(record))}</h2><div class="gallery-meta"><span>▣ ${esc(formatDate(p.shoot_date))}</span><span>⌖ ${esc(place.label)}</span></div><span class="status ${status[1]}">${status[0]}</span>${index===0?`<button class="primary gallery-cta" data-project="${record.id}">Open project →</button>`:`<button class="link gallery-link" data-project="${record.id}">View project →</button>`}</div></article>`}
function bind(){document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>go(button.dataset.view));document.querySelectorAll('[data-project]').forEach(button=>button.onclick=()=>go('project',button.dataset.project));document.querySelectorAll('[data-brief]').forEach(button=>button.onclick=()=>showBrief(button.dataset.brief));document.querySelectorAll('[data-production]').forEach(button=>button.onclick=()=>showProduction(button.dataset.production));document.querySelectorAll('[data-schedule]').forEach(button=>button.onclick=()=>showSchedule(button.dataset.schedule));document.querySelectorAll('[data-plan-approve]').forEach(button=>button.onclick=()=>approveProduction(button.dataset.planApprove));document.querySelectorAll('[data-generate-plan]').forEach(button=>button.onclick=()=>generateProduction(button.dataset.generatePlan));document.querySelectorAll('[data-generate-moodboard]').forEach(button=>button.onclick=()=>generateMoodboard(button.dataset.generateMoodboard))}
function overview(){setNav('overview');const attention=inquiries.filter(item=>['READY_FOR_REVIEW','CLIENT_CONFIRMED','CLIENT_CHANGE_REQUESTED'].includes(item.status)||item.production_pack&&!item.production_approved),scheduled=inquiries.filter(item=>item.status==='SCHEDULED').sort((a,b)=>String(a.call_time||payload(a).shoot_date||'').localeCompare(String(b.call_time||payload(b).shoot_date||''))),priority=attention[0]||scheduled[0],active=inquiries.filter(item=>item.status!=='SCHEDULED').slice(0,2).concat(inquiries.filter(item=>item.status==='SCHEDULED').slice(0,2)).slice(0,2);let priorityCard='<section class="overview-priority card"><div><div class="eyebrow">Studio status</div><h2>Everything is up to date.</h2><p class="muted">New client activity and planning tasks will appear here.</p></div><button class="secondary" data-view="inquiries">Open inquiry inbox →</button></section>';if(priority){const p=payload(priority),needsAction=attention.includes(priority),place=projectLocation(priority);priorityCard=`<section class="overview-priority card"><div><div class="eyebrow">${needsAction?'Needs your attention':'Next scheduled shoot'}</div><h2>${esc(needsAction?projectTitle(priority):p.client_name||projectTitle(priority))}</h2><p>${esc(needsAction?statusInfo(priority)[0].toLowerCase():`${formatDate(priority.call_time||p.shoot_date)} · ${place.label}`)}</p></div><button class="primary" data-project="${priority.id}">${needsAction?'Continue planning':'Open call sheet'} →</button></section>`}app.innerHTML=`<div class="overview-shell"><header class="overview-head"><div><div class="eyebrow">Photographer workspace</div><h1>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc((sessionUser.name||'there').split(' ')[0])}.</h1><p class="lede">${inquiries.length} active shoot${inquiries.length===1?'':'s'} · ${attention.length?`${attention.length} item${attention.length===1?'':'s'} need your attention`:'Everything is up to date'}</p></div><button class="secondary" data-view="inquiries">Open inquiry inbox →</button></header>${priorityCard}<div class="overview-metrics"><div><b>${inquiries.filter(x=>x.status==='READY_FOR_REVIEW').length}</b><span>New inquiries</span></div><div><b>${inquiries.filter(x=>x.status==='NEEDS_INFORMATION').length}</b><span>Awaiting client</span></div><div><b>${inquiries.filter(x=>x.status==='CLIENT_CONFIRMED').length}</b><span>Ready to schedule</span></div><div><b>${scheduled.length}</b><span>Upcoming shoots</span></div></div><section class="overview-section"><div class="section-head"><div><div class="eyebrow">Coming up</div><h2 class="section-title">Upcoming schedule</h2></div><button class="link" data-view="calendar">View calendar →</button></div><div class="overview-schedule">${scheduled.slice(0,2).map(record=>{const p=payload(record);return`<article class="card schedule-preview"><time>${esc(formatDate(record.call_time||p.shoot_date))}</time><div><h3>${esc(p.client_name||projectTitle(record))}</h3><p class="muted">${esc(record.meeting_location||'Meeting location pending')}</p></div><button class="link" data-project="${record.id}">Open project →</button></article>`}).join('')||'<div class="card muted">No scheduled shoots yet.</div>'}</div></section><section class="overview-section"><div class="section-head"><div><div class="eyebrow">Current work</div><h2 class="section-title">Active projects</h2></div><button class="link" data-view="projects">View all projects →</button></div><div class="overview-projects">${active.map((record,index)=>galleryProject(record,index+1)).join('')||'<div class="card muted">No active projects yet.</div>'}</div></section></div>`;bind()}
function listView(kind){setNav(kind);const title=kind==='inquiries'?'Inquiry inbox':'Active projects',copy=kind==='inquiries'?'Every client request and follow-up in one place.':'Move each shoot from creative direction to production and scheduling.';if(kind==='projects'){app.innerHTML=`<div class="head"><div><div class="eyebrow">Photographer workspace</div><h1>${title}</h1><p class="lede">${copy}</p></div></div><div class="gallery-shell"><div class="gallery-grid">${inquiries.map(galleryProject).join('')||'<div class="card muted">Nothing here yet.</div>'}</div></div>`}else{app.innerHTML=`<div class="head"><div><div class="eyebrow">Photographer workspace</div><h1>${title}</h1><p class="lede">${copy}</p></div></div>${inquiries.map(recordCard).join('')||'<div class="card muted">Nothing here yet.</div>'}`}bind()}
function calendar(){setNav('calendar');const scheduled=inquiries.filter(x=>x.status==='SCHEDULED').sort((a,b)=>String(a.call_time).localeCompare(String(b.call_time)));app.innerHTML=`<div class="head"><div><div class="eyebrow">Shoot calendar</div><h1>Upcoming sessions</h1><p class="lede">Confirmed call times and meeting locations from your active projects.</p></div></div><div class="calendar">${scheduled.map(record=>{const p=payload(record);return`<article class="card"><div class="calendar-date">${esc(formatDate(record.call_time))}</div><h3>${esc(p.client_name)}</h3><p class="muted">${esc(record.meeting_location||'Meeting location pending')}</p><button class="link" data-project="${record.id}">Open project →</button></article>`}).join('')||'<div class="card muted">No shoots have been scheduled yet.</div>'}</div>`;bind()}
function progress(record){const hasMood=!!record.moodboard,hasPack=!!record.production_pack;return`<div class="progress"><div class="done"><b>01 · Inquiry</b>Details captured</div><div class="${hasMood?'done':''}"><b>02 · Creative direction</b>${hasMood?'Moodboard ready':'Brief review'}</div><div class="${hasPack?'done':''}"><b>03 · Production</b>${hasPack?'Plan created':'Shoot planning'}</div><div class="${record.status==='SCHEDULED'?'done':''}"><b>04 · Schedule</b>${record.status==='SCHEDULED'?'Shoot booked':'Client confirmation'}</div></div>`}
async function project(id){setNav('project');const record=await getRecord(id),p=payload(record),analysis=parse(record.analysis)||{},mood=parse(record.moodboard),status=statusInfo(record);let next='Waiting for the client to provide the remaining details.',button='';if(record.status==='SCHEDULED')next=`Shoot scheduled for ${formatDate(record.call_time)} at ${record.meeting_location}.`;else if(record.status==='CLIENT_CONFIRMED'){next='The client confirmed the plan. Set the final call time and meeting location.';button=`<button class="primary" data-schedule="${id}">Set shoot schedule →</button>`}else if(record.status==='CLIENT_CHANGE_REQUESTED'){next='The client requested a change. Review the inquiry and update the direction.';button=`<button class="primary" data-brief="${id}">Review creative brief →</button>`}else if(record.production_pack){next=record.production_approved?'The production plan is with the client for confirmation.':'Review and approve the production plan.';button=`<button class="primary" data-production="${id}">Review production pack →</button>`}else if(mood){next='The moodboard is ready. Turn the direction into a shoot-day plan.';button=`<button class="primary" data-generate-plan="${id}">Generate production pack →</button>`}else if(record.status==='READY_FOR_REVIEW'){next='The inquiry is complete. Review the creative brief before generating references.';button=`<button class="primary" data-brief="${id}">Review creative brief →</button>`}app.innerHTML=`<button class="link" data-view="projects">← Back to Active projects</button><div class="detail-head"><div class="eyebrow">Active project · Inquiry #${record.id}</div><div class="row"><h1>${esc(p.client_name)}</h1><span class="status ${status[1]}">${status[0]}</span></div></div>${progress(record)}<div class="detail-grid"><section class="card"><div class="eyebrow">Client inquiry</div><p>${esc((p.message||'').split('\n\nClient follow-up answers:')[0])}</p><div class="followup"><div class="eyebrow">Client follow-up answers</div><p>${esc((p.message||'').includes('Client follow-up answers:')?p.message.split('Client follow-up answers:').slice(1).join(' '):'No follow-up answers recorded.')}</p></div><p class="quote">${esc(analysis.summary||'Agent summary is being prepared.')}</p><div class="meta"><div>Budget<b>${p.budget?'$'+esc(p.budget):'—'}</b></div><div>Date<b>${esc(formatDate(p.shoot_date))}</b></div><div>Contact<b>${esc(p.contact_email||p.client_email)}</b></div></div></section><aside class="card next"><div class="eyebrow">Your next move</div><h2>${esc(next)}</h2><div class="actions">${button}</div></aside></div>${mood?moodboardMarkup(mood):''}`;bind()}
function moodboardMarkup(mood){const tiles=mood.generated?.tiles||[];return`<section class="card moodboard"><div class="eyebrow">Approved moodboard</div><h2 class="section-title">${esc(mood.moodboard?.title||mood.generated?.title||'Creative direction')}</h2><div class="tiles">${tiles.map(tile=>`<figure><img src="${esc(tile.image_url)}" alt="${esc(tile.title)}"><figcaption>${esc(tile.title)}</figcaption></figure>`).join('')}</div></section>`}
async function showBrief(id){current={view:'brief',id:Number(id)};setNav('brief');history.pushState(current,'',`/photographer?view=brief&id=${id}`);app.innerHTML='<div class="loading">Preparing the creative brief…</div>';try{const record=await getRecord(id),p=payload(record);let brief=briefCache.get(Number(id));if(!brief){const response=await fetch('/api/inquiries/brief',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({inquiry:p,client_answers:{},inquiry_id:Number(id)})});if(!response.ok)throw Error('Could not create the brief.');brief=await response.json();briefCache.set(Number(id),brief)}app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Creative brief · ${esc(p.client_name)}</div><h1>${esc(brief.concept_name)}</h1><p class="lede">Review this direction before rendering the visual moodboard.</p></div><section class="card">${briefField('Creative summary',brief.creative_summary)}${briefField('Location',brief.location_direction)}${briefField('Lighting',brief.lighting_direction)}${briefField('Posing',brief.posing_direction)}${briefField('Wardrobe',brief.wardrobe_direction)}${briefField('Deliverables',(brief.deliverables||[]).join(', '))}${briefField('Budget notes',brief.budget_notes)}<div class="actions"><button class="primary" data-generate-moodboard="${id}">Approve brief and generate moodboard →</button></div><div id="operationStatus"></div></section>`;bind()}catch(error){showError(error.message)}}
const briefField=(title,value)=>`<div class="field-row"><b>${title}</b>${esc(value||'—')}</div>`;
async function generateMoodboard(id){const button=document.querySelector('[data-generate-moodboard]'),status=document.getElementById('operationStatus');button.disabled=true;button.textContent='Rendering moodboard…';status.innerHTML='<div class="notice">Generating four visual references. This can take a few minutes.</div>';try{const brief=briefCache.get(Number(id)),response=await fetch('/api/moodboards/create-and-generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({brief,inquiry_id:Number(id)})}),raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{data={detail:response.ok?'The server returned an unreadable response.':'Moodboard generation failed on the server.'}}if(!response.ok)throw Error(data.detail||data.error||'Moodboard generation failed.');await refresh();project(id)}catch(error){status.innerHTML=`<div class="error"><b>Moodboard was not generated.</b><br>${esc(error.message||'Please try again in a moment.')}</div>`;button.disabled=false;button.textContent='Try generating moodboard again →'}}
async function generateProduction(id){current={view:'production',id:Number(id)};history.pushState(current,'',`/photographer?view=production&id=${id}`);setNav('production');app.innerHTML='<div class="loading">Building the production pack…</div>';try{const record=await getRecord(id),p=payload(record);const response=await fetch(`/api/production-packs/create?inquiry_id=${id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({inquiry:p,client_answers:{},inquiry_id:Number(id)})});const data=await response.json();if(!response.ok)throw Error(data.detail||'Could not create the production pack.');await refresh();showProduction(id,false)}catch(error){showError(error.message)}}
async function showProduction(id,push=true){current={view:'production',id:Number(id)};if(push)history.pushState(current,'',`/photographer?view=production&id=${id}`);setNav('production');const record=await getRecord(id),pack=parse(record.production_pack);if(!pack){app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="card"><h2>No production pack yet</h2><button class="primary" data-generate-plan="${id}">Generate production pack →</button></div>`;bind();return}app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Production pack</div><h1>${esc(pack.title)}</h1><p class="lede">Review the shoot-day details before sharing the finalized plan with the client.</p></div><section class="card"><div class="eyebrow">Call sheet</div><div class="call-sheet">${Object.entries(pack.call_sheet||{}).map(([key,value])=>`<div><small>${esc(key)}</small><b>${esc(value)}</b></div>`).join('')}</div></section><div class="plan-grid">${planSection('Location plan',pack.location_plan)}${planSection('Shot list',pack.shot_list)}${planSection('Lighting plan',pack.lighting_plan)}${planSection('Wardrobe checklist',pack.wardrobe_checklist)}${planSection('Weather note',[pack.weather_note])}${planSection('Backup plan',[pack.backup_plan])}</div><section class="card"><div class="eyebrow">Photographer review</div>${record.production_approved?'<div class="notice"><b>Production pack approved</b><br>The client can now review and confirm this plan.</div>':`<p>This plan is ready to share with the client.</p><button class="primary" data-plan-approve="${id}">Approve production pack →</button>`}</section>`;bind()}
const planSection=(title,values)=>`<section class="card"><div class="eyebrow">${title}</div><ul>${(values||[]).map(value=>`<li>${esc(value)}</li>`).join('')}</ul></section>`;
async function approveProduction(id){const response=await fetch(`/api/inquiries/${id}/production/approve`,{method:'POST'});const data=await response.json();if(!response.ok||data.error){showError(data.detail||data.error||'Could not approve the production pack.');return}await refresh();showProduction(id,false)}
async function showSchedule(id){current={view:'schedule',id:Number(id)};history.pushState(current,'',`/photographer?view=schedule&id=${id}`);setNav('schedule');const record=await getRecord(id);app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Final scheduling</div><h1>Set the shoot details.</h1><p class="lede">The client confirmed the plan. Choose the final call time and meeting point.</p></div><form class="card schedule-form" id="scheduleForm"><div class="field"><label for="callTime">Call time</label><input id="callTime" type="datetime-local" value="${esc(record.call_time||'')}" required></div><div class="field"><label for="meetingLocation">Meeting location</label><input id="meetingLocation" value="${esc(record.meeting_location||'')}" placeholder="e.g. Pike Place Market, main entrance" required></div><button class="primary" id="scheduleButton">Confirm schedule →</button><span id="scheduleStatus" class="muted"></span></form>`;bind();document.getElementById('scheduleForm').onsubmit=event=>saveSchedule(event,id)}
async function saveSchedule(event,id){event.preventDefault();const button=document.getElementById('scheduleButton'),status=document.getElementById('scheduleStatus');button.disabled=true;status.textContent='Saving schedule…';try{const response=await fetch(`/api/inquiries/${id}/schedule`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({call_time:document.getElementById('callTime').value,meeting_location:document.getElementById('meetingLocation').value})});const data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save the schedule.');await refresh();project(id)}catch(error){status.textContent=error.message;button.disabled=false}}
function showError(message){app.innerHTML=`<div class="error"><b>Something went wrong</b><br>${esc(message)}</div><div class="actions"><button class="secondary" data-view="projects">Return to projects</button></div>`;bind()}
async function getRecord(id){const cached=inquiries.find(item=>item.id==id);if(cached)return cached;return fetch('/api/inquiries/'+id).then(response=>response.json())}
async function refresh(){const response=await fetch('/api/inquiries?photographer_email='+encodeURIComponent(sessionUser.email||''));inquiries=await response.json();document.getElementById('inboxCount').textContent=inquiries.filter(x=>['READY_FOR_REVIEW','CLIENT_CONFIRMED','CLIENT_CHANGE_REQUESTED'].includes(x.status)).length||''}
function renderCurrent(){if(current.view==='overview')overview();else if(current.view==='inquiries'||current.view==='projects')listView(current.view);else if(current.view==='calendar')calendar();else if(current.view==='project')project(current.id);else if(current.view==='brief')showBrief(current.id);else if(current.view==='production')showProduction(current.id);else if(current.view==='schedule')showSchedule(current.id)}
async function editProduction(id){const record=await getRecord(id),pack=parse(record.production_pack);if(!pack)return;current={view:'production',id:Number(id)};app.innerHTML=`<button class="link" data-production="${id}">← Cancel editing</button><div class="detail-head"><div class="eyebrow">Production pack draft</div><h1>Edit the shoot plan</h1><p class="lede">Save a draft as often as needed. Sharing is a separate action.</p></div><form class="card" id="productionEditForm"><div class="field"><label>Plan title</label><input name="title" value="${esc(pack.title||'')}" required></div>${['location_plan','shot_list','lighting_plan','wardrobe_checklist'].map(key=>`<div class="field"><label>${esc(key.replaceAll('_',' '))}</label><textarea name="${key}" required>${esc((pack[key]||[]).join('\n'))}</textarea><small class="muted">One item per line</small></div>`).join('')}<div class="field"><label>Weather note</label><textarea name="weather_note" required>${esc(pack.weather_note||'')}</textarea></div><div class="field"><label>Backup plan</label><textarea name="backup_plan" required>${esc(pack.backup_plan||'')}</textarea></div>${Object.entries(pack.call_sheet||{}).map(([key,value])=>`<div class="field"><label>${esc(key.replaceAll('_',' '))}</label><input name="call_${esc(key)}" value="${esc(value)}"></div>`).join('')}<div class="actions"><button class="primary" type="submit">Save draft →</button><span id="draftStatus" class="muted"></span></div></form>`;bind();document.getElementById('productionEditForm').onsubmit=event=>saveProductionDraft(event,id,pack)}
async function saveProductionDraft(event,id,existing){event.preventDefault();const form=event.currentTarget,status=document.getElementById('draftStatus'),button=form.querySelector('button[type="submit"]'),value=name=>form.elements[name]?.value||'';button.disabled=true;status.textContent='Saving draft…';const lines=name=>value(name).split('\n').map(item=>item.trim()).filter(Boolean);const call_sheet=Object.fromEntries(Object.keys(existing.call_sheet||{}).map(key=>[key,value(`call_${key}`)]));const pack={title:value('title'),location_plan:lines('location_plan'),shot_list:lines('shot_list'),lighting_plan:lines('lighting_plan'),wardrobe_checklist:lines('wardrobe_checklist'),weather_note:value('weather_note'),backup_plan:value('backup_plan'),call_sheet};try{const response=await fetch(`/api/inquiries/${id}/production-pack`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(pack)}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not save the draft.');await refresh();status.textContent='Draft saved. Share it when ready.';setTimeout(()=>showProduction(id,false),500)}catch(error){status.textContent=error.message;button.disabled=false}}
