async function init(){try{cityImages=await fetch('/static/city-images.json?v=2',{cache:'no-store'}).then(response=>response.json())}catch{cityImages={}}await refresh();const params=new URLSearchParams(location.search),view=params.get('view')||'overview',id=params.get('id');current={view,id:id?Number(id):null};history.replaceState(current,'',location.href);renderCurrent()}
