async function showPhotographerMessages(id){const record=await getRecord(id),p=payload(record),response=await fetch(`/api/inquiries/${id}/messages`,{cache:'no-store'}),messages=response.ok?await response.json():[];setNav('project');app.innerHTML=`<button class="link" data-project="${id}">← Back to project</button><div class="detail-head"><div class="eyebrow">Client conversation</div><h1>${esc(p.client_name||'Client')}</h1><p class="lede">Messages for this inquiry stay with the production context.</p></div><section class="card conversation"><div class="conversation-list">${messages.map(message=>`<article class="message ${message.sender_role==='photographer'?'mine':''}"><small>${esc(message.sender_name)} · ${esc(formatDate(message.created_at))}</small><p>${esc(message.body)}</p></article>`).join('')||'<p class="muted">No messages yet. Start the conversation with the client.</p>'}</div><form id="photographerMessageForm" class="message-compose"><textarea id="messageBody" required maxlength="4000" placeholder="Write a message…"></textarea><div class="actions"><button class="primary">Send message →</button><span id="messageStatus" class="muted"></span></div></form></section>`;bind();document.getElementById('photographerMessageForm').onsubmit=event=>sendPhotographerMessage(event,id)}
async function sendPhotographerMessage(event,id){event.preventDefault();const button=event.currentTarget.querySelector('button'),status=document.getElementById('messageStatus'),body=document.getElementById('messageBody').value.trim();if(!body)return;button.disabled=true;status.textContent='Sending…';try{const response=await fetch(`/api/inquiries/${id}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body,sender_role:'photographer',sender_name:sessionUser.name||'Photographer'})}),raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{data={detail:'The server could not send this message. Please try again.'}}if(!response.ok)throw Error(data.detail||'Could not send your message.');await showPhotographerMessages(id)}catch(error){status.textContent=error.message;button.disabled=false}}
