function photographerMessageInbox(){setNav('messages');app.innerHTML=`<div class="head"><div><div class="eyebrow">Client conversations</div><h1>Messages</h1><p class="lede">Keep every client conversation connected to its inquiry.</p></div></div><div class="conversation-inbox">${inquiries.map(record=>{const p=payload(record);return`<article class="card conversation-preview"><div><div class="eyebrow">Inquiry #${record.id}</div><h2>${esc(p.client_name||'Client')}</h2><p class="muted">${esc(projectTitle(record))}</p></div><button class="primary" data-message-client="${record.id}">Open conversation →</button></article>`}).join('')||'<div class="card muted">No client conversations yet.</div>'}</div>`;bind()}
