const renderPhotographerMessagesWorkspace=renderCurrent;renderCurrent=()=>{if(current.view==='messages')return current.id?showPhotographerMessages(current.id):photographerMessageInbox();return renderPhotographerMessagesWorkspace()};
function updatePhotographerMessageNotices(){const total=inquiries.reduce((sum,record)=>sum+Number(record.unread_messages||0),0),messagesButton=document.querySelector('.nav button[data-view="messages"]');if(messagesButton){let badge=messagesButton.querySelector('.unread-message-badge');if(total){if(!badge){badge=document.createElement('span');badge.className='unread-message-badge';messagesButton.appendChild(badge)}badge.textContent=total>99?'99+':total;messagesButton.title=`${total} unread client message${total===1?'':'s'}`}else badge?.remove()}}
function decoratePhotographerUnread(){document.querySelectorAll('[data-project],[data-message-client]').forEach(button=>{const id=button.dataset.project||button.dataset.messageClient,record=inquiries.find(item=>item.id==id),count=Number(record?.unread_messages||0),card=button.closest('.card,.gallery-card');if(!count||!card||card.querySelector('.inquiry-unread'))return;card.insertAdjacentHTML('afterbegin',`<span class="inquiry-unread">${count} new message${count===1?'':'s'}</span>`)});updatePhotographerMessageNotices()}
