function projectSections(){const needsAttention=inquiries.filter(record=>Number(record.unread_messages||0)>0||['READY_FOR_REVIEW','CLIENT_CHANGE_REQUESTED','CLIENT_CONFIRMED'].includes(record.status)),scheduled=inquiries.filter(record=>record.status==='SCHEDULED'),inProgress=inquiries.filter(record=>!needsAttention.includes(record)&&!scheduled.includes(record));return[['Needs attention','Client messages, approvals, and shoot decisions that need your response.',needsAttention],['In progress','Creative direction, moodboards, and production planning in motion.',inProgress],['Scheduled','Confirmed sessions that are ready for shoot day.',scheduled]]}
function projectsView(){setNav('projects');const sections=projectSections();app.innerHTML=`<div class="head projects-head"><div><div class="eyebrow">Photographer workspace</div><h1>Projects</h1><p class="lede">A clear view of every shoot, organized by the next action.</p></div></div><div class="project-sections">${sections.map(([name,description,records])=>`<section class="project-section"><div class="section-head"><div><div class="eyebrow">${records.length} shoot${records.length===1?'':'s'}</div><h2 class="section-title">${name}</h2><p class="muted">${description}</p></div></div>${records.length?`<div class="gallery-grid project-section-grid">${records.map((record,index)=>galleryProject(record,index)).join('')}</div>`:'<div class="project-section-empty">Nothing in this section right now.</div>'}</section>`).join('')}</div>`;bind();decoratePhotographerUnread()}
