function photographerMessageInbox(){setNav('messages');const conversations=inquiries.filter(record=>Number(record.message_count||0)>0).sort((a,b)=>String(b.latest_message?.created_at||'').localeCompare(String(a.latest_message?.created_at||'')));app.innerHTML=`<div class="head"><div><div class="eyebrow">Client conversations</div><h1>Messages</h1><p class="lede">Only conversations that have been started, with each shoot’s essential context close at hand.</p></div></div><div class="conversation-inbox">${conversations.map(record=>{const p=payload(record),latest=record.latest_message||{},status=statusInfo(record),when=record.call_time?formatDate(record.call_time):p.shoot_date?`Preferred date · ${formatDate(p.shoot_date)}`:'Date to be confirmed',location=record.meeting_location||'Location being planned',unread=Number(record.unread_messages||0);return`<article class="card conversation-preview rich-conversation"><div class="conversation-main"><div class="conversation-heading"><div><div class="eyebrow">Inquiry #${record.id}</div><h2>${esc(p.client_name||'Client')}</h2></div><span class="status ${status[1]}">${status[0]}</span></div><p class="conversation-title">${esc(projectTitle(record))}</p><div class="conversation-context"><span>▣ ${esc(when)}</span><span>⌖ ${esc(location)}</span></div><div class="last-message"><b>${esc(latest.sender_name||'Client')}</b><span>${esc(latest.body||'')}</span><small>${esc(formatDate(latest.created_at))}</small></div></div><div class="conversation-action">${unread?`<span class="inquiry-unread inline-unread">${unread} new</span>`:''}<button class="primary" data-message-client="${record.id}">Open conversation →</button></div></article>`}).join('')||'<div class="card muted">No conversations have been started yet.</div>'}</div>`;bind();decoratePhotographerUnread()}
async function photographerCalendar(){setNav('calendar');const response=await fetch('/api/availability?photographer_email='+encodeURIComponent(sessionUser.email||'')+'&include_unavailable=true'),slots=response.ok?await response.json():[],requested=slots.filter(slot=>slot.status==='REQUESTED'),available=slots.filter(slot=>slot.status==='AVAILABLE'),booked=slots.filter(slot=>slot.status==='BOOKED');const clientName=id=>payload(inquiries.find(record=>record.id==id)||{}).client_name||'Client';app.innerHTML=`<div class="head"><div><div class="eyebrow">Shoot calendar</div><h1>Schedule & availability</h1><p class="lede">Offer times, review client requests, and confirm the final shoot schedule.</p></div></div><div class="availability-layout"><section class="card availability-create"><div class="eyebrow">Add availability</div><h2>Open a time for booking</h2><form id="availabilityForm"><div class="field"><label>Start</label><input name="starts_at" type="datetime-local" required></div><div class="field"><label>End</label><input name="ends_at" type="datetime-local" required></div><div class="field"><label>Meeting location</label><input name="location" placeholder="e.g. Pioneer Square, main entrance" required></div><div class="actions"><button class="primary">Add available time →</button><span id="availabilityStatus" class="muted"></span></div></form></section><section class="card availability-requests"><div class="eyebrow">Pending requests</div><h2>${requested.length} client request${requested.length===1?'':'s'}</h2>${requested.map(slot=>`<article class="availability-row"><div><b>${esc(clientName(slot.inquiry_id))}</b><span>${esc(formatDate(slot.starts_at))} – ${esc(new Date(slot.ends_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}</span><small>${esc(slot.location)}</small></div><button class="primary" data-confirm-slot="${slot.id}">Confirm booking →</button></article>`).join('')||'<p class="muted">No pending time requests.</p>'}</section></div><section class="availability-section"><div class="section-head"><div><div class="eyebrow">Available times</div><h2 class="section-title">Ready for clients</h2></div></div><div class="availability-list">${available.map(slot=>`<article class="card availability-row"><div><b>${esc(formatDate(slot.starts_at))} – ${esc(new Date(slot.ends_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}))}</b><span>${esc(slot.location)}</span></div><span class="status ready">AVAILABLE</span></article>`).join('')||'<p class="muted">No available times yet.</p>'}</div></section>${booked.length?`<section class="availability-section"><div class="eyebrow">Booked</div><div class="availability-list">${booked.map(slot=>`<article class="card availability-row"><div><b>${esc(formatDate(slot.starts_at))}</b><span>${esc(clientName(slot.inquiry_id))} · ${esc(slot.location)}</span></div><span class="status scheduled">BOOKED</span></article>`).join('')}</div></section>`:''}`;bind();document.getElementById('availabilityForm').onsubmit=saveAvailabilitySlot}
async function saveAvailabilitySlot(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),status=document.getElementById('availabilityStatus');button.disabled=true;status.textContent='Saving…';try{const response=await fetch('/api/availability?photographer_email='+encodeURIComponent(sessionUser.email||''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),data=await response.json();if(!response.ok)throw Error(data.detail||'Could not add availability.');await photographerCalendar()}catch(error){status.textContent=error.message;button.disabled=false}}
