async function photographerSmartCalendar(){setNav('calendar');const response=await fetch('/api/calendar?photographer_email='+encodeURIComponent(sessionUser.email||''),{cache:'no-store'}),data=response.ok?await response.json():{entries:[]},entries=data.entries||[];const records=Object.fromEntries(inquiries.map(item=>[item.id,item])),start=new Date();start.setHours(0,0,0,0);const days=Array.from({length:14},(_,index)=>{const day=new Date(start);day.setDate(day.getDate()+index);return day}),pending=entries.filter(item=>item.kind==='requested');app.innerHTML=`<div class="head"><div><div class="eyebrow">Shoot calendar</div><h1>Your studio, in rhythm.</h1><p class="lede">Confirmed shoots and client time preferences, arranged around your real availability.</p></div></div>${pending.length?`<section class="card scheduling-queue"><div><div class="eyebrow">Needs confirmation</div><h2>${pending.length} preferred time${pending.length===1?'':'s'} awaiting you</h2></div>${pending.map(item=>{const p=payload(records[item.inquiry_id]||{});return`<article><div><b>${esc(p.client_name||'Client')} · ${esc(photographerCalendarDate(item.starts_at))}</b><span>${esc(photographerCalendarTime(item.starts_at))} – ${esc(photographerCalendarTime(item.ends_at))} · ${esc(item.location||'Location to be confirmed')}</span></div><button class="primary" data-confirm-request="${item.inquiry_id}" data-time="${esc(item.starts_at)}" data-location="${esc(item.location||'Location to be confirmed')}">Review & confirm →</button></article>`}).join('')}</section>`:''}<section class="calendar-board"><div class="calendar-board-head"><b>${esc(start.toLocaleDateString(undefined,{month:'long',year:'numeric'}))}</b><span>${entries.filter(item=>item.kind==='scheduled').length} shoot${entries.filter(item=>item.kind==='scheduled').length===1?'':'s'} confirmed</span></div><div class="calendar-week">${days.map(day=>{const key=day.toISOString().slice(0,10),events=entries.filter(item=>String(item.starts_at).slice(0,10)===key);return`<article class="calendar-day ${events.length?'has-event':''}"><div><small>${esc(day.toLocaleDateString(undefined,{weekday:'short'}))}</small><b>${day.getDate()}</b></div>${events.map(item=>{const p=payload(records[item.inquiry_id]||{});return`<button class="calendar-event ${item.kind}" data-project="${item.inquiry_id}">${esc(photographerCalendarTime(item.starts_at))}<span>${esc(p.client_name||'Client')} · ${esc(item.kind==='scheduled'?'Confirmed':'Requested')}</span></button>`}).join('')}</article>`}).join('')}</div></section>`;bind()}
async function openScheduleConfirmation(button){const id=button.dataset.confirmRequest,record=await getRecord(id),p=payload(record);app.innerHTML=`<button class="link" data-view="calendar">← Back to shoot calendar</button><div class="detail-head"><div class="eyebrow">Confirm shoot time</div><h1>Make it official.</h1><p class="lede">The client selected a preferred time. You can keep it or make a final adjustment before confirming.</p></div><form class="card schedule-confirm-form" id="scheduleConfirmForm"><div class="field"><label>Client</label><input value="${esc(p.client_name||'Client')}" disabled></div><div class="field"><label>Date and time</label><input name="call_time" type="datetime-local" value="${esc(button.dataset.time)}" required></div><div class="field"><label>Meeting location</label><input name="meeting_location" value="${esc(button.dataset.location)}" required></div><div class="actions"><button class="primary">Confirm shoot →</button><span class="muted" id="scheduleConfirmStatus"></span></div></form>`;bind();document.getElementById('scheduleConfirmForm').onsubmit=event=>confirmSmartSchedule(event,id)}
async function confirmSmartSchedule(event,id){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),status=document.getElementById('scheduleConfirmStatus');button.disabled=true;status.textContent='Confirming shoot…';try{const data=Object.fromEntries(new FormData(form)),response=await fetch(`/api/inquiries/${id}/schedule-confirmation?photographer_email=${encodeURIComponent(sessionUser.email||'')}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),result=await response.json();if(!response.ok)throw Error(result.detail||'Could not confirm this shoot.');await refresh();go('calendar')}catch(error){status.textContent=error.message;button.disabled=false}}
